const canvas = document.createElement('canvas');
canvas.width = 1080;
canvas.height = 1440;
const ctx = canvas.getContext('2d');

// 暖色背景
const gradient = ctx.createLinearGradient(0, 0, 1080, 1440);
gradient.addColorStop(0, '#FAF7F2');
gradient.addColorStop(1, '#F5EDE4');
ctx.fillStyle = gradient;
ctx.fillRect(0, 0, 1080, 1440);

// 装饰性植物元素
ctx.fillStyle = '#7D9B76';
// 简单叶子
for(let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.ellipse(100 + i*200, 200, 40, 80, Math.PI/4, 0, Math.PI*2);
    ctx.fill();
}

// 书本区域（简化表示）
const bookColors = ['#E8D5C4', '#D4C4B0', '#C9B8A3', '#B8A890', '#A69880'];
const bookTitles = ['蛤蟆先生', '被讨厌的勇气', '当下的力量', '云边有个小卖部', '山茶文具店'];

for(let i = 0; i < 5; i++) {
    const x = 150 + (i % 3) * 280;
    const y = i < 3 ? 450 : 750;

    // 书本背景
    ctx.fillStyle = bookColors[i];
    ctx.fillRect(x, y, 220, 280);

    // 书脊
    ctx.fillStyle = 'rgba(0,0,0,0.1)';
    ctx.fillRect(x + 200, y, 20, 280);

    // 书名区域
    ctx.fillStyle = '#FFF';
    ctx.fillRect(x + 20, y + 40, 180, 200);

    // 书名文字
    ctx.fillStyle = '#5A4A3A';
    ctx.font = 'bold 20px sans-serif';
    ctx.textAlign = 'center';
    const lines = bookTitles[i].match(/.{1,4}/g) || [bookTitles[i]];
    lines.forEach((line, idx) => {
        ctx.fillText(line, x + 110, y + 100 + idx * 30);
    });
}

// 咖啡杯
ctx.fillStyle = '#D4A574';
ctx.beginPath();
ctx.arc(800, 1000, 60, 0, Math.PI*2);
ctx.fill();
ctx.fillStyle = '#C49464';
ctx.beginPath();
ctx.arc(800, 1000, 50, 0, Math.PI*2);
ctx.fill();

// 标题
ctx.fillStyle = '#5A4A3A';
ctx.font = 'bold 60px sans-serif';
ctx.textAlign = 'center';
ctx.fillText('治愈系书单', 540, 1200);

ctx.font = '36px sans-serif';
ctx.fillStyle = '#8B7355';
ctx.fillText('读完这5本书，我突然不焦虑了', 540, 1280);

// 装饰线
ctx.strokeStyle = '#C4B8A8';
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(340, 1330);
ctx.lineTo(740, 1330);
ctx.stroke();

// 小红书风格标签
ctx.fillStyle = '#FF2442';
ctx.font = '24px sans-serif';
ctx.fillText('#读书推荐  #治愈书单  #焦虑自救', 540, 1380);

// 输出
const dataUrl = canvas.toDataURL('image/png');
console.log('配图已生成');
dataUrl;
